Rep_NA <- function(x) {
  Q1 <- quantile(x, 0.25, na.rm = TRUE); Q3 <- quantile(x, 0.75, na.rm = TRUE); IQR_val <- Q3 - Q1;
  lower <- Q1 - 1.5 * IQR_val;   upper <- Q3 + 1.5 * IQR_val; ifelse(x < lower | x > upper, NA, x)}
