#01. Load necessary libraries, set ggplot theme
set.seed(312)
library(ggplot2); library(scales); library(reshape2); library(pheatmap); library(UpSetR); library(igraph); library(dplyr)
my_theme <- theme(text = element_text(size = 14, face = "bold"), plot.title = element_text(size = 18, face = "bold"), plot.subtitle = element_text(size = 12, face = "bold"), axis.title = element_text(size = 14, face = "bold"), axis.text = element_text(size = 12, face = "bold"), legend.title = element_text(size = 12, face = "bold"), legend.text = element_text(size = 10, face = "bold"))

#02. Perform Beta value and M value once each
#ALL_CORR_LIP <- B01_LIP_CRPVb_HyPi; setwd("G:/내 드라이브/Rrunning/HW014/Output_B01_LIP/Bvalue")
ALL_CORR_LIP <- B01_LIP_CRPVm_HyPi; setwd("G:/내 드라이브/Rrunning/HW014/Output_B01_LIP/Mvalue")
head(ALL_CORR_LIP); table(ALL_CORR_LIP$Var); dim(ALL_CORR_LIP) # 3 vars, 9922 rows

#03. Select top 100 variables (based on absolute Pi score)
VAR_Select_No <- 100
ALL_CORR_LIP <- as.data.frame(ungroup(slice_max(group_by(ALL_CORR_LIP, CLASS, Var), order_by = abs(Pi), n = VAR_Select_No)))
table(ALL_CORR_LIP[,c(4,9)]); dim(ALL_CORR_LIP)

#04.Wide format conversion and sex data separation
ALL_CORR_LIPt <- as.data.frame(table(ALL_CORR_LIP[,c(4,9)]))
ALL_CORR_LIPt <- ALL_CORR_LIPt[order(ALL_CORR_LIPt$Freq), ]
ALL_CORR_LIPw <- as.data.frame.matrix(xtabs(Freq ~ CLASS + Var, data = ALL_CORR_LIPt))

ALL_CORR_M_LIP <- dplyr::filter(ALL_CORR_LIP, Sex=="M")
ALL_CORR_F_LIP <- dplyr::filter(ALL_CORR_LIP, Sex=="F")

#05. Global Connectivity Map (Analysis by cancer condition)
ALL_CORR_M_LIP$Comparison <- NA
ALL_CORR_M_LIP$Comparison[grepl("NT", ALL_CORR_M_LIP$CLASS)] <- "NT"
ALL_CORR_M_LIP$Comparison[grepl("Tm1", ALL_CORR_M_LIP$CLASS)] <- "T1"
ALL_CORR_M_LIP$Comparison[grepl("Tm2", ALL_CORR_M_LIP$CLASS)] <- "T2"
HyPi_M_HM_LIP <- aggregate(HyPiPi ~ TCGA + Var + Comparison, data = ALL_CORR_M_LIP, FUN = mean)

ALL_CORR_F_LIP$Comparison <- NA
ALL_CORR_F_LIP$Comparison[grepl("NT", ALL_CORR_F_LIP$CLASS)] <- "NT"
ALL_CORR_F_LIP$Comparison[grepl("Tm1", ALL_CORR_F_LIP$CLASS)] <- "T1"
ALL_CORR_F_LIP$Comparison[grepl("Tm2", ALL_CORR_F_LIP$CLASS)] <- "T2"
HyPi_F_HM_LIP <- aggregate(HyPiPi ~ TCGA + Var + Comparison, data = ALL_CORR_F_LIP, FUN = mean)

#06. Figure 1. Global Connectivity Map (LIP)
HyPi_M_HMp_LIP <- ggplot(data = HyPi_M_HM_LIP, aes(x = Var, y = TCGA, fill = HyPiPi)) + geom_tile(color = "white") + 
  scale_fill_gradient2(low = "#03AED2",mid="#FFFDF5",high = "#D12052", midpoint = 0, limits = c(-15, 15), oob = scales::squish) + facet_grid(. ~ Comparison) + theme_bw() + labs(x = "Male:   3 Variables of lipid metabolism", y = "TCGA Cancer Types") + theme(axis.text.x = element_text(angle = 45, hjust = 1)) + my_theme
HyPi_F_HMp_LIP <- ggplot(data = HyPi_F_HM_LIP, aes(x = Var, y = TCGA, fill = HyPiPi)) + geom_tile(color = "white") + 
  scale_fill_gradient2(low = "#03AED2",mid="#FFFDF5",high = "#D12052", midpoint = 0, limits = c(-15, 15), oob = scales::squish) + facet_grid(. ~ Comparison) + theme_bw() + labs(x = "Female: 3 Variables of lipid metabolism", y = "TCGA Cancer Types") + theme(axis.text.x = element_text(angle = 45, hjust = 1)) + my_theme
ggsave("01_GlobConMap_LIP.pdf", plot=grid.arrange(HyPi_M_HMp_LIP, HyPi_F_HMp_LIP, ncol=2), width= 8, height=8)

